class Critique(BaseModel):
    passes: bool
    issues: list[str]      # e.g. ["missing unit test", "unhandled None"]

# the optimizer revises against SPECIFIC issues, not vibes
def revise(task, draft, critique):
    fixes = "; ".join(critique.issues)
    return generate(f"{task}\nFix exactly these: {fixes}\nPrior: {draft}")

