# fake 'generator' that improves once it sees the failure
def generate(task, feedback=None):
    if feedback and "handle zero" in feedback:
        return "def inv(x): return 0 if x == 0 else 1 / x"
    return "def inv(x): return 1 / x"          # first draft misses x == 0

def evaluate(code):
    ns = {}
    exec(code, ns)
    try:
        ns["inv"](0)                            # the checkable test
        return {"passes": True, "issue": None}
    except ZeroDivisionError:
        return {"passes": False, "issue": "handle zero input"}

draft = generate("safe reciprocal")
for _ in range(3):
    verdict = evaluate(draft)
    if verdict["passes"]:
        break
    draft = generate("safe reciprocal", feedback=verdict["issue"])

print(draft)
print("passes:", evaluate(draft)["passes"])

def criticize(draft):
    # structured critique against explicit criteria
    issues = []
    if "summary" not in draft:
        issues.append("add a summary line")
    if len(draft) < 20:
        issues.append("too short")
    return {"passes": not issues, "issues": issues}

def revise(draft, issues):
    if "add a summary line" in issues:
        draft = "summary: " + draft
    if "too short" in issues:
        draft = draft + " (expanded with detail)"
    return draft

draft = "raw"
prev = None
for round_i in range(5):
    c = criticize(draft)
    if c["passes"]:
        break
    if draft == prev:               # no progress -> stop
        break
    prev = draft
    draft = revise(draft, c["issues"])

print(draft)
print("passed:", criticize(draft)["passes"])

