def reflect(task, generate, evaluate, max_rounds=4):
    draft = generate(task, feedback=None)   # initial draft
    prev = None
    for _ in range(max_rounds):
        verdict = evaluate(draft)
        if verdict["passes"]:
            return draft                    # good enough -> stop
        if draft == prev:
            return draft                    # no progress -> stop
        prev = draft
        draft = generate(task, feedback=verdict["issues"])  # revise
    return draft                            # budget hit: best effort

