# generator improves each round until it satisfies the evaluator
def generate(task, feedback):
    if feedback is None:
        return "a"
    if "need b" in feedback:
        return "ab"
    if "need c" in feedback:
        return "abc"
    return "abc"

def evaluate(draft):
    issues = []
    if "b" not in draft:
        issues.append("need b")
    if "c" not in draft:
        issues.append("need c")
    return {"passes": not issues, "issues": issues}

assert reflect("t", generate, evaluate) == "abc"

# a generator stuck on the same draft must stop on no-improvement
def stuck(task, feedback):
    return "x"
def never(draft):
    return {"passes": False, "issues": ["more"]}
out = reflect("t", stuck, never, max_rounds=10)
assert out == "x"
print("all tests passed")

