from typing import Callable

def reflect(task: str,
            generate: Callable,      # generate(task, feedback) -> str
            evaluate: Callable,      # evaluate(draft) -> {passes, issues}
            max_rounds: int = 4) -> str:
    draft = generate(task, feedback=None)   # first draft
    prev = None
    for _ in range(max_rounds):
        verdict = evaluate(draft)
        if verdict["passes"]:
            return draft                     # stop: good enough
        if draft == prev:
            return draft                     # stop: no progress
        prev = draft
        draft = generate(task, feedback=verdict["issues"])  # revise
    return draft                             # stop: budget hit

if __name__ == "__main__":
    def generate(task, feedback):
        if feedback is None:
            return "draft"
        return "draft summary" if "add summary" in feedback else "draft"
    def evaluate(d):
        issues = [] if "summary" in d else ["add summary"]
        return {"passes": not issues, "issues": issues}
    print(reflect("write note", generate, evaluate))
